package com.gmail.manhle240406.project.adoption;
import android.os.*;import android.widget.*;import android.view.*;
import androidx.test.core.app.ActivityScenario;import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.platform.app.InstrumentationRegistry;import androidx.test.uiautomator.*;import androidx.lifecycle.ViewModelProvider;
import com.gmail.manhle240406.project.*;import com.gmail.manhle240406.project.R;import com.gmail.manhle240406.project.pet.*;import com.gmail.manhle240406.project.community.*;
import com.google.android.gms.tasks.Tasks;import com.google.firebase.auth.FirebaseAuth;import org.junit.*;import org.junit.runner.RunWith;import java.util.*;import java.util.concurrent.atomic.*;
import static org.junit.Assert.*;import static org.hamcrest.Matchers.*;import static androidx.test.espresso.Espresso.*;import static androidx.test.espresso.action.ViewActions.*;import static androidx.test.espresso.matcher.ViewMatchers.*;import static androidx.test.espresso.assertion.ViewAssertions.*;import static com.gmail.manhle240406.project.adoption.AdoptionFlowModel.*;
@RunWith(AndroidJUnit4.class) public final class DocFeedbackDeviceTest {
 private String uid;private final AtomicInteger registrations=new AtomicInteger();private final AtomicBoolean submitted=new AtomicBoolean();private Map<String,Object> intent;
 private static final String PET="10000000-0000-0000-0000-000000000081";
 @Before public void setup(){OwnedPets.clear();uid=FirebaseAuth.getInstance().getUid();assertNotNull("Keep the existing signed-in account",uid);AdoptionApi.testTransport=(op,input)->{if(op.equals("workspace")||op.equals("petWorkspace"))return Tasks.forResult(map("pets",submitted.get()?Arrays.asList(map("petId",PET,"identityVersion",1,"identity",map("displayName","Synthetic feedback pet","species","cat"),"claim",map("reviewState","submitted","claimVersion",1))):new ArrayList<>(),"offers",new ArrayList<>(),"drafts",new ArrayList<>(),"reviewer",new ArrayList<>()));if(op.equals("registerPet")){registrations.incrementAndGet();intent=new HashMap<>(input);submitted.set(true);return Tasks.forResult(map("petId",PET,"status","submitted"));}return Tasks.forResult(map());};}
 @After public void cleanup(){AdoptionApi.testTransport=null;assertEquals(uid,FirebaseAuth.getInstance().getUid());}
 private void waitText(int resource){String value=InstrumentationRegistry.getInstrumentation().getTargetContext().getString(resource);assertTrue("Expected "+value,UiDevice.getInstance(InstrumentationRegistry.getInstrumentation()).wait(Until.hasObject(By.text(value)),15000));}
 private void edit(){waitText(R.string.ad_add_pet);onView(withText(R.string.ad_add_pet)).perform(click());}
 @Test public void registrationIsOneActionAndShowsPendingStatus(){try(ActivityScenario<PetActivity> scenario=ActivityScenario.launch(PetActivity.class)){edit();onView(withTagValue(equalTo("pet_name"))).perform(scrollTo(),replaceText("Synthetic feedback pet"),androidx.test.espresso.action.ViewActions.closeSoftKeyboard());onView(withTagValue(equalTo("pet_register_submit"))).perform(scrollTo(),click());waitText(R.string.feedback_pet_registered);onView(withText(R.string.feedback_pet_pending)).check(matches(isDisplayed()));assertEquals(1,registrations.get());assertEquals(0,((List<?>)intent.get("mediaAssetIds")).size());assertNotNull(intent.get("operationId"));capture("pet-pending");}}
 @Test public void cancelCanContinueEditingAndRotationRetainsDraft(){try(ActivityScenario<PetActivity> scenario=ActivityScenario.launch(PetActivity.class)){edit();onView(withTagValue(equalTo("pet_name"))).perform(scrollTo(),replaceText("Synthetic local draft"),androidx.test.espresso.action.ViewActions.closeSoftKeyboard());onView(withText(R.string.feedback_cancel)).perform(scrollTo(),click());onView(withText(R.string.feedback_continue_editing)).perform(click());onView(withTagValue(equalTo("pet_name"))).perform(scrollTo()).check(matches(withText("Synthetic local draft")));scenario.recreate();onView(withTagValue(equalTo("pet_name"))).perform(scrollTo()).check(matches(withText("Synthetic local draft")));capture("pet-registration");onView(withText(R.string.feedback_cancel)).perform(scrollTo(),click());onView(withText(R.string.feedback_discard)).perform(click());waitText(R.string.ad_add_pet);assertEquals(0,registrations.get());}}
 @Test public void composerUsesOptionalSwitchAndPhotoGrid(){try(ActivityScenario<SocialComposerActivity> scenario=ActivityScenario.launch(SocialComposerActivity.class)){onView(withId(R.id.post_type_picker)).check(matches(isNotChecked()));onView(withId(R.id.adoption_listing_action)).check(matches(withEffectiveVisibility(Visibility.GONE)));onView(withId(R.id.post_type_picker)).perform(click());onView(withId(R.id.adoption_listing_action)).check(matches(isDisplayed()));onView(withId(R.id.post_type_picker)).perform(click());onView(withId(R.id.adoption_listing_action)).check(matches(withEffectiveVisibility(Visibility.GONE)));onView(withText(R.string.media_add_photos)).perform(scrollTo());capture("composer-grid");}}
 @Test public void profileEditingDismissesAndMainNavigationRemainsVisible(){try(ActivityScenario<MainActivity> scenario=ActivityScenario.launch(MainActivity.class)){scenario.onActivity(a->a.navigate("profile"));onView(withId(R.id.profile_edit)).perform(click());onView(withId(R.id.profile_public_fields)).check(matches(isDisplayed()));onView(withText(R.string.oc2_cancel)).perform(click());onView(withId(R.id.profile_public_fields)).check(matches(withEffectiveVisibility(Visibility.GONE)));onView(withId(R.id.profile_edit)).perform(click());onView(withText(R.string.oc2_cancel)).perform(click());onView(withId(R.id.nav_home)).check(matches(isDisplayed()));onView(withId(R.id.profile_discovery)).check(matches(withEffectiveVisibility(Visibility.GONE)));capture("profile");}}
 private void capture(String name){android.graphics.Bitmap bitmap=InstrumentationRegistry.getInstrumentation().getUiAutomation().takeScreenshot();assertNotNull(bitmap);java.io.File dir=new java.io.File(InstrumentationRegistry.getInstrumentation().getTargetContext().getExternalFilesDir(null),"doc-feedback-ui");assertTrue(dir.mkdirs()||dir.isDirectory());try(java.io.FileOutputStream out=new java.io.FileOutputStream(new java.io.File(dir,name+".png"))){bitmap.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}catch(java.io.IOException e){throw new AssertionError(e);}finally{bitmap.recycle();}}
}
